import { IEndpoints } from '../types';

import { getEndpoints as getDKEndpoints } from './dk-endpoints';
import { getEndpoints as getESEndpoints } from './es-endpoints';
import { getEndpoints as getItEndpoints } from './it-endpoints';
import { getEndpoints as getSEEndpoints } from './se-endpoints';
import { getEndpoints as getUkEndpoints } from './uk-endpoints';
import { queryStringParams } from '../services/query-string';

export function getEndpoints(): IEndpoints {
    const region = queryStringParams.locale;

    switch (region) {
        case 'it-it':
            return getItEndpoints();
        case 'es-es':
            return getESEndpoints();
        case 'dk-dk':
            return getDKEndpoints();
        case 'se-se':
            return getSEEndpoints();
        default:
            return getUkEndpoints();
    }
}
